API_URL = os.environ.get("VST_LLM_API_URL", "")
API_KEY = os.environ.get("VST_LLM_API_KEY", "")


# --- 1. LLM API 封装 ---

def call_llm_api(prompt_content, system_prompt=""):
    """
    封装你的 API 调用接口
    """
    url = API_URL # 请确保替换为实际地址
    headers = {
        "Content-Type": "application/json",
        "X-API-Key": API_KEY  # 替换为您的API密钥
    }

    payload = {
        # "model": "gemini-2.5-pro", "gemini-3-flash"
        "model": "gemini-3-flash",
        "key_id": 1,
        "contents": prompt_content,
        "system_prompt": system_prompt
    }

    try:
        # 在实际运行中，请取消下面这行的注释
        response = requests.post(url, headers=headers, data=json.dumps(payload), timeout=30)

        result = response.json()
        res =  result.get("results", "")  # 根据实际API返回结构调整
        return res[0]
        
    except Exception as e:
        print(f"API Call Error: {e}")
        return "{}"



